SBOS_TimerSet.example:
static void on_tick(void *user) { (void)user; }
CGTimer timer = SBOS_CreateTimer();
if (timer != CGTIMER_INVALID) {
    SBOS_TimerSet(timer, 100, 100, on_tick, NULL);
}

