   dbug outputs a message for debugging. */
dbug("About menu chosen");

uint8_t data[64];
uint32_t count = 0;
if (sfopen(0, "/hello.txt",
           SD_READ | SD_OPEN_EXISTING) == FR_OK) {
    if (sfread(0, data, sizeof(data), &count) == FR_OK) {
        /* Exactly count bytes were read. */
    }
    sfclose(0);
}

/* Inside On_messenger1_Message(...) USER block:
   message is provided by generated code. */
