const char text[] = "PING";
uint32_t recipient = API->ipc->find("ipc_rx.app");
if (recipient != 0) {
    int32_t result = API->ipc->send(
        recipient, 1u, text, sizeof(text) - 1u);
    if (result == SIDBOX_IPC_OK) {
        dbug("Message sent");
    }
}

